    sub_ddmmss(cw1, cw0, UWORD(0x0001a01a01a01a01), UWORD(0xa01a01a01a01a01a), h, l);

    /* cos V_2  (4 x 2) */
    P[0] = UWORD(0);
    P[1] = UWORD(0);
    P[2] = cw0; P[3] = cw1;
    flint_mpn_mulhigh_n(T, z + 3, P, 4);
    P[0] = UWORD(0xb05b05b05b05b05b);
    P[1] = UWORD(0x5b05b05b05b05b05);
    P[2] = UWORD(0x05b05b05b05b05b0);
    P[3] = UWORD(0x005b05b05b05b05b);
    NN_SUB_4(cV, P, T);

    /* cos V_1  (5 x 4) */
    P[0] = UWORD(0);
    P[1] = cV[0];
    P[2] = cV[1];
    P[3] = cV[2];
    P[4] = cV[3];
    flint_mpn_mulhigh_n(T, z + 2, P, 5);
    P[0] = UWORD(0xaaaaaaaaaaaaaaaa);
    P[1] = UWORD(0xaaaaaaaaaaaaaaaa);
    P[2] = UWORD(0xaaaaaaaaaaaaaaaa);
    P[3] = UWORD(0xaaaaaaaaaaaaaaaa);
    P[4] = UWORD(0x0aaaaaaaaaaaaaaa);
    NN_SUB_5(cV, P, T);

    /* cos V_0  (6 x 5) */
    P[0] = UWORD(0);
    P[1] = cV[0];
    P[2] = cV[1];
    P[3] = cV[2];
    P[4] = cV[3];
    P[5] = cV[4];
    flint_mpn_mulhigh_n(T, z + 1, P, 6);
    P[0] = UWORD(0x0000000000000000);
    P[1] = UWORD(0x0000000000000000);
    P[2] = UWORD(0x0000000000000000);
    P[3] = UWORD(0x0000000000000000);
    P[4] = UWORD(0x0000000000000000);
    P[5] = UWORD(0x8000000000000000);
    NN_SUB_6(cV, P, T);

    /* sin = x - x^3 V_0 */
    P[0] = UWORD(0);
    P[1] = UWORD(0);
    P[2] = sV[0];
    P[3] = sV[1];
    P[4] = sV[2];
    P[5] = sV[3];
    P[6] = sV[4];
